:\"item\"}}},\"as\":\"it\",\"do\":{\"op\":\"object\",\"fields\":{\"item\":{\"var\":\"it\"},\"reserved\":{\"op\":\"sum\",\"value\":{\"op\":\"map\",\"items\":{\"op\":\"filter\",\"items\":{\"var\":\"active\"},\"as\":\"e\",\"do\":{\"op\":\"eq\",\"args\":[{\"op\":\"get\",\"value\":{\"var\":\"e\"},\"key\":\"item\"},{\"var\":\"it\"}]}},\"as\":\"e\",\"do\":{\"op\":\"get\",\"value\":{\"var\":\"e\"},\"key\":\"quantity\"}}},\"available\":{\"op\":\"sub\",\"args\":[{\"op\":\"max_by\",\"items\":{\"op\":\"filter\",\"items\":{\"var\":\"stock\"},\"as\":\"s\",\"do\":{\"op\":\"eq\",\"args\":[{\"op\":\"get\",\"value\":{\"var\":\"s\"},\"key\":\"item\"},{\"var\":\"it\"}]}},\"as\":\"s\",\"key\":{\"op\":\"get\",\"value\":{\"var\":\"s\"},\"key\":\"capacity\"}}]}}}}}}}}}}}}}"
